      {
        id: "java-c12-u5-l4-cancelamento-de-futures-e-futuretask",
        title: "Cancelamento com future.cancel(boolean) e a classe FutureTask",
        subtitle: "Controle de ciclo de vida · Interrupção voluntária e tarefas independentes",
        theory: "O método future.cancel(boolean mayInterruptIfRunning) tenta abortar uma tarefa. Se passado true, ele envia thread.interrupt() se ela já estiver rodando. Além disso, FutureTask<V> é a implementação concreta base que reúne Runnable e Future, permitindo controlar e encadear execuções assíncronas manualmente.",
        questions: [
          q("Qual é o efeito do argumento booleano true na chamada future.cancel(true)?", "Permite que a JVM interrompa a thread de trabalho via interrupção caso ela já esteja executando", ["Força o encerramento do processo do sistema operacional","Garante que a tarefa termine com sucesso"], "Com true, o thread que executa a tarefa recebe um sinal de interrupção imediato."),
          q("O que acontece se future.cancel(false) for chamado em uma tarefa que já está em andamento?", "A tarefa não é interrompida e continua executando, mas seu resultado final não poderá ser lido", ["A tarefa é pausada temporariamente","Gera um erro fatal no console"], "Com false, tarefas em execução são deixadas terminar, mas futuras chamadas get() lançam CancellationException."),
          q("Qual classe do Java implementa simultaneamente as interfaces Runnable e Future<V>?", "java.util.concurrent.FutureTask<V>", ["java.lang.Thread","java.util.concurrent.Executors"], "FutureTask é uma abstração utilitária que une o comportamento de tarefa executável e promessa de resultado."),
          q("Após cancelar uma tarefa com sucesso com future.cancel(true), o que future.isCancelled() devolve?", "true", ["false","null"], "isCancelled() reflete fielmente se a operação foi abortada antes da conclusão normal."),
          t("Qual método da interface Future cancela a execução da tarefa em andamento?", ["cancel"], "cancel() aborta tarefas pendentes ou em execução no ExecutorService."),
          g("Complete o cancelamento permitindo que a thread trabalhadora sofra interrupção imediata:", ["cancel"], "future.cancel(true) envia sinal de interrupção para tarefas ativas.", "boolean abortado = futuro.____(true);"),
          o("Ordene os estados de uma tarefa que sofre cancelamento antes de sua conclusão:", ["A tarefa é enfileirada no pool e aguarda um trabalhador disponível","O controlador detecta timeout e invoca future.cancel(true)","O ExecutorService marca a tarefa como cancelada e envia interrupção","Chamadas subsequentes a future.get() lançam CancellationException"], "Enfileiramento, chamada de cancel(), marcação e lançamento de CancellationException."),
          p("Associe o método de controle de tarefa ao seu efeito na execução:", [["cancel(true)","Envia interrupção para a thread trabalhadora se ela já estiver em execução"],["cancel(false)","Impede o início da tarefa se ainda na fila, sem interromper ativas"],["FutureTask<V>","Classe concreta que empacota Callable e pode ser executada em threads"],["CancellationException","Exceção não-checada lançada ao chamar get() em tarefa cancelada"]], "Dominar cancelamento e FutureTask evita desperdício de CPU em computações abandonadas.")
        ]
      },
      {
        id: "java-c12-u5-l5-padroes-de-orquestracao-com-invokeall-e-invokeany",
        title: "Padrões de orquestração com invokeAll() e invokeAny()",
        subtitle: "Processamento em lote · Coordenando grupos de tarefas assíncronas no pool",
        theory: "O ExecutorService oferece métodos utilitários para coleções de Callable: invokeAll() executa todas as tarefas e retorna uma lista de Future após todas terminarem (ou quando expira o timeout). Já invokeAny() executa um conjunto de tarefas concorrentes e devolve o resultado da primeira que concluir com êxito.",
        questions: [
          q("Qual é o comportamento do método executor.invokeAll(listaDeCallables)?", "Bloqueia até que todas as tarefas da lista tenham sido concluídas e devolve uma lista de Futures", ["Executa apenas a primeira tarefa e descarta as demais","Lança um erro se houver mais de duas tarefas"], "invokeAll orquestra o processamento completo em lote de múltiplas tarefas Callable."),
          q("Qual é o caso de uso ideal para o método executor.invokeAny(listaDeCallables)?", "Consultar múltiplos servidores espelho e utilizar a resposta do primeiro que responder com sucesso", ["Executar tarefas que precisam rodar estritamente em sequência","Salvar dados no banco de forma transacional"], "invokeAny é ótimo para redundância: o mais rápido vence e os outros são cancelados."),
          q("O que acontece com as demais tarefas quando invokeAny() obtém o primeiro resultado de sucesso?", "As tarefas restantes não concluídas são automaticamente canceladas pelo framework", ["Elas continuam executando em segundo plano até o fim dos tempos","Elas travam o computador"], "O framework cancela as concorrentes perdedoras assim que uma vence a disputa."),
          q("O método invokeAll() aceita um parâmetro de tempo limite (timeout) para o lote todo?", "Sim; se o tempo expirar, as tarefas incompletas são canceladas e a lista de futures é devolvida", ["Não, timeouts só existem para tarefas individuais","Apenas no Java 8 em diante"], "invokeAll(tarefas, timeout, unidade) previne que uma única tarefa lenta atrase o lote inteiro."),
          t("Qual método do ExecutorService executa uma coleção de tarefas e devolve o primeiro resultado bem-sucedido?", ["invokeAny"], "invokeAny seleciona o resultado da primeira tarefa concorrente a finalizar."),
          g("Complete a execução do lote de tarefas aguardando a finalização de todas elas:", ["invokeAll"], "invokeAll executa todas as tarefas Callable da lista.", "List<Future<Cotacao>> futuros = executor.____(tarefasCotacao);"),
          o("Ordene a rotina de busca de dados em múltiplos provedores usando invokeAny:", ["Montar a lista de tarefas Callable conectando a diferentes servidores espelho","Chamar executor.invokeAny(provedores) disparando as requisições em paralelo","O provedor mais rápido responde com sucesso entregando seu resultado","O ExecutorService cancela automaticamente as conexões mais lentas"], "Montagem da lista, disparo com invokeAny, retorno do vencedor e cancelamento dos demais."),
          p("Associe o método de orquestração ao seu comportamento operacional:", [["invokeAll()","Aguarda todas as tarefas finalizarem e devolve lista com todos os Futures"],["invokeAny()","Retorna o valor da primeira tarefa a concluir com sucesso e aborta o resto"],["invokeAll com timeout","Cancela as tarefas que não concluíram dentro da janela limite"],["Coleção de Callable","Estrutura padrão de entrada para submissão em lote de tarefas no pool"]], "Saber escolher entre invokeAll e invokeAny otimiza o tempo de resposta em sistemas paralelos.")
        ]
      }
